# region: gather
def gather(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: digest
def digest(xs):
    return [v for v in xs if v % 2 == 0]

# region: intake
def intake(xs):
    return [v * v for v in xs[1:]]

# region: shape
def shape(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: render
def render(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return render(shape(intake(digest(gather(raw)))))

