        self.assertEqual(run(['12', '12', '1']), {'n': 2, 'total': 288.0, 'grade': 'high'})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'total': 0.0, 'grade': 'low'})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'total': 144.0, 'grade': 'high'})
